{
  "units": [
    {
      "quote": "An applicant with a pending name change must not be issued a passport in her/his new name.",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "prohibition",
      "meaning": "An applicant whose name change court order or decree is pending (not final) must not be issued a passport in their new name."
    },
    {
      "quote": "See 8 FAM 1001.5 regarding applying for a replacement passport in a new name;",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "background",
      "meaning": "Provides a cross-reference to 8 FAM 1001.5 concerning applications for a replacement passport in a new name, carrying no independent operational rule."
    },
    {
      "quote": "An applicant with a pending name change must not be issued a form FS-240 in her/his new name.",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "prohibition",
      "meaning": "An applicant whose name change court order or decree is pending (not final) must not be issued a Form FS-240 in their new name."
    },
    {
      "quote": "See 8 FAM 1001.3 regarding amending a form FS-240; and",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "background",
      "meaning": "Provides a cross-reference to 8 FAM 1001.3 regarding amending a Form FS-240, carrying no independent operational rule."
    },
    {
      "quote": "You must clear the applicant's pending name even though the name change is not final and even if the passport is not being issued at this time.",
      "scope_quotes": ["c. The court order or decree must be final:"],
      "kind": "requirement",
      "meaning": "The adjudicator must clear the applicant's pending name despite the name change not being final and regardless of whether the passport is currently being issued."
    },
    {
      "quote": "The court order or decree must list both the applicant's current and former name(s).",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "A submitted court order or decree must show both the applicant's current name and former name(s)."
    },
    {
      "quote": "You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program).",
      "scope_quotes": ["The court order or decree must list both the applicant's current and former name(s)."],
      "kind": "exception",
      "meaning": "As an exception to the requirement that the court order list both former and current names, an order may be received where the applicant's former name is kept confidential (such as under California's Safe at Home program)."
    },
    {
      "quote": "When this occurs, the applicant must provide both her/his current and former names on the application.",
      "scope_quotes": ["The court order or decree must list both the applicant's current and former name(s).", "EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."],
      "kind": "requirement",
      "meaning": "If the court order keeps the applicant's former name confidential, the applicant must still provide both their current and former names on the passport application."
    },
    {
      "quote": "You may request additional evidence of U.S. citizenship/non-citizen U.S. nationality or identity in accordance with 22 CFR 51.23 and 22 CFR 51.45.",
      "scope_quotes": ["EXCEPTION: You may receive a court order in which the applicant's former name is made confidential (e.g., California's Safe at Home program)."],
      "kind": "permission",
      "meaning": "When handling a case with a court order keeping the former name confidential, adjudicators are authorized to request additional identity or citizenship/non-citizen U.S. nationality evidence pursuant to 22 CFR 51.23 and 22 CFR 51.45."
    },
    {
      "quote": "8 FAM 403.1-3(B) Name Spacing\n\n(CT:CITZ-96; 08-04-2023)",
      "scope_quotes": [],
      "kind": "background",
      "meaning": "Section title and administrative circular metadata."
    },
    {
      "quote": "In accordance with International Civil Aviation Organization (ICAO) recommendations, U.S. passports, form FS-240, and form DS-2060 are printed in all uppercase letters.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "States that U.S. passports, Form FS-240, and Form DS-2060 are printed entirely in uppercase letters pursuant to ICAO recommendations."
    },
    {
      "quote": "Printing a name with multiple parts in uppercase letters causes the name to appear as one word unless the parts are separated with spaces.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Describes the factual consequence that multi-part names printed in all uppercase appear as a single word if spaces do not separate the parts."
    },
    {
      "quote": "Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "If an applicant has a name consisting of multiple parts, the adjudicator must make a determination regarding how the name will be formatted and appear."
    },
    {
      "quote": "If the applicant's previous passport had a space, you should add a space on the current application;",
      "scope_quotes": ["Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"],
      "kind": "recommendation",
      "meaning": "When an applicant with a multi-part name had a space in their previous passport, the adjudicator is advised to add a space on the current application."
    },
    {
      "quote": "If the applicant does not have a previous passport and the applicant's evidence of U.S. citizenship/non-citizen U.S. nationality or ID has a space, you should add a space on the current application; or",
      "scope_quotes": ["Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"],
      "kind": "recommendation",
      "meaning": "When an applicant with a multi-part name lacks a previous passport but their citizenship/nationality evidence or ID includes a space, the adjudicator is advised to add a space on the current application."
    },
    {
      "quote": "If the applicant expresses a clear preference to add or remove space, either verbally or in writing, you may add or remove it per the applicant's preference.",
      "scope_quotes": ["Consequently, if the applicant has a name with multiple parts, you must determine how the name will appear:"],
      "kind": "permission",
      "meaning": "When an applicant with a multi-part name states a clear preference (either in writing or verbally) to add or remove space, the adjudicator is authorized to add or remove it according to that preference."
    },
    {
      "quote": "If you receive applications from several family members, you should space the last names consistently, unless a family member expresses a clear preference for a different spacing.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "When processing applications from multiple members of the same family, the adjudicator should space the family members' last names consistently, except when an individual family member explicitly prefers different spacing."
    },
    {
      "quote": "For special-issuance passports, the spacing of an eligible family member's last name should match the spacing of the last name of the sponsor.",
      "scope_quotes": [],
      "kind": "recommendation",
      "meaning": "In the context of special-issuance passports, the spacing of an eligible family member's last name should be aligned to match the sponsor's last name spacing."
    },
    {
      "quote": "Name spacing issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Issues regarding name spacing generally do not justify rewriting a passport, unless the Department failed to follow an applicant's clearly expressed preference."
    },
    {
      "quote": "Arabic ordinal numbers must be changed to Roman numerals, for example, 2nd to II, 3rd to III:",
      "scope_quotes": [],
      "kind": "requirement",
      "meaning": "Arabic ordinal numbers appearing in names must be converted into Roman numerals (e.g., converting 2nd to II, or 3rd to III)."
    },
    {
      "quote": "Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English.",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Observes that some applicants might use the prefix 'Sr.' to represent the Spanish title 'Señor' ('Mr.' or 'Mister' in English)."
    },
    {
      "quote": "If you determine that this is the case, follow the guidance in 8 FAM 403.1-5(C) regarding ranks and titles.",
      "scope_quotes": ["Some applicants may include the prefix “Sr.” as an abbreviation for “Señor” in Spanish meaning “Mr.” or “Mister” in English."],
      "kind": "requirement",
      "meaning": "If an adjudicator finds that 'Sr.' is being used as an abbreviation for 'Señor', they must adhere to the procedures for ranks and titles detailed in 8 FAM 403.1-5(C)."
    },
    {
      "quote": "Name suffix issues are generally not sufficient cause to rewrite a passport, unless the Department disregarded the applicant's clear preference (see 8 FAM 1001.2).",
      "scope_quotes": [],
      "kind": "statement",
      "meaning": "Name suffix issues do not generally constitute sufficient grounds for a passport rewrite, unless the Department disregarded the applicant's clearly expressed preference."
    }
  ]
}
